import React from 'react';

import ActionCard, { ActionCardProps } from '~components/action-card';

import { PermutationsPage } from '../app/templates';
import createPermutations from '../utils/permutations';
import PermutationsView from '../utils/permutations-view';
import {
  icon,
  longContent,
  longDescription,
  longHeader,
  onClick,
  shortContent,
  shortDescription,
  shortHeader,
} from './common';

const permutations = createPermutations<ActionCardProps>([
  // All content slots filled
  {
    header: [shortHeader],
    description: [shortDescription],
    children: [shortContent],
    icon: [icon],
    iconVerticalAlignment: ['top'],
    onClick: [onClick],
  },
  // Header variations
  {
    header: [shortHeader, longHeader, undefined],
    description: [shortDescription],
    children: [shortContent],
    ariaLabel: ['Action card'],
    onClick: [onClick],
  },
  // Description variations
  {
    header: [shortHeader],
    description: [shortDescription, longDescription, undefined],
    children: [shortContent],
    onClick: [onClick],
  },
  // Icon with alignment variations
  {
    header: [shortHeader],
    description: [shortDescription],
    icon: [icon],
    iconVerticalAlignment: ['top', 'center'],
    onClick: [onClick],
  },
  // Icon with children content
  {
    header: [shortHeader],
    children: [shortContent],
    icon: [icon],
    iconVerticalAlignment: ['top', 'center'],
    onClick: [onClick],
  },
  // Disabled state
  {
    header: [shortHeader],
    description: [shortDescription],
    children: [shortContent],
    icon: [icon],
    iconVerticalAlignment: ['top', 'center'],
    disabled: [true],
    onClick: [onClick],
  },
  // Long content wrapping
  {
    header: [longHeader],
    description: [longDescription],
    children: [longContent],
    icon: [icon],
    iconVerticalAlignment: ['top', 'center'],
    onClick: [onClick],
  },
  // Minimal: content only
  {
    children: [shortContent],
    ariaLabel: ['Minimal card'],
    onClick: [onClick],
  },
  // Header only
  {
    header: [shortHeader],
    onClick: [onClick],
  },
]);

export default function ActionCardPermutations() {
  return (
    <PermutationsPage title="Action card permutations" i18n={{}}>
      <PermutationsView permutations={permutations} render={permutation => <ActionCard {...permutation} />} />
    </PermutationsPage>
  );
}

